/**
 * Patch notes of the hub: one package per go-live day, newest first. Every change that reaches `main` adds its
 * entries here (rule in CLAUDE.md). Self-contained (no imports) so tests can check it directly.
 *
 * Admins see every entry. Customers see only entries marked `customers: true`, freelancers only those marked
 * `freelancers: true` (since 18.11.2026), each only packages that contain one; the package summary is for admins. Texts are plain German for people who use the hub, never names, addresses,
 * keys or infrastructure details.
 *
 * Every entry names one of six areas and the place in the hub where the change happened (22.11.2026), so the patch
 * notes read as a table: Art · Bereich & Stelle · Änderung.
 */

export type PatchChangeKind = "new" | "improved" | "fixed" | "security";

/**
 * The six areas of the hub an entry belongs to (consolidated, user 21.11.2026):
 * - start: Übersicht and Insights (welcome, notifications on the overview, widgets, tiles)
 * - projects: Projekte, task board, Kalender, appointments and Studio
 * - files: Dateien and the Asset Management
 * - customers: customer data: Vertrag & Domain, Schlüsselbund, customer records, the freelancers' „Kunden“
 * - messages: Nachrichten (chat), the bell, the hub's e-mails and Telegram
 * - hub: everything around it: sign-in, Profil, Darstellung, navigation, User Management and logins, Assistent,
 *   Claude, KI-Protokoll, legal pages, Patch Notes and general fixes
 */
export type PatchArea = "start" | "projects" | "files" | "customers" | "messages" | "hub";

export const patchAreaLabels: Record<PatchArea, string> = {
  start: "Übersicht & Insights",
  projects: "Projekte & Kalender",
  files: "Dateien",
  customers: "Kunden & Verträge",
  messages: "Chat & Benachrichtigungen",
  hub: "Hub & Konto",
};

/** The order of the areas in filters and groups. */
export const patchAreaOrder: readonly PatchArea[] = ["start", "projects", "files", "customers", "messages", "hub"];

export type PatchChange = {
  kind: PatchChangeKind;
  /** The area of the hub the change belongs to. */
  area: PatchArea;
  /** Where exactly, as the hub names it, levels joined by „ › “: "Kalender › Freie Zeiten". */
  place: string;
  /** Further areas the change touches, shown as „auch: …“. */
  also?: PatchArea[];
  title: string;
  text: string;
  /** Shown to customers as well; without it the entry stays internal. */
  customers?: true;
  /** Shown to freelancers (18.11.2026): what concerns them, worded so it holds for them; without it they never see it. */
  freelancers?: true;
};

export type PatchPackage = {
  number: number;
  /** Go-live day, YYYY-MM-DD. */
  date: string;
  /** Shown to customers as well, so it names only changes they see; internal topics belong in the summary. */
  title: string;
  /** For freelancers when the title names things they do not have (Vertrag & Domain, say). */
  freelancerTitle?: string;
  /** What the package is about, for admins. */
  summary: string;
  changes: PatchChange[];
};

export const patchKindLabels: Record<PatchChangeKind, string> = {
  new: "Neu",
  improved: "Verbessert",
  fixed: "Behoben",
  security: "Sicherheit",
};

